@RestController
public class HelloController {

    private final GreetingService service;

    public HelloController(GreetingService service) {
        this.service = service;
    }

    @GetMapping(value = "/hello", produces = "text/plain;charset=UTF-8")
    public String hello() {
        return "hello spring";
    }

    @GetMapping(value = "/greet", produces = "text/plain;charset=UTF-8")
    public String greet(@RequestParam String name) {
        return service.greet(name);
    }
}

@Configuration
@ComponentScan(basePackages = "study.embed")
public class SpringConfig {
    @Bean
    public GreetingService greetingService() {
        return new GreetingService();
    }
}


-- main 에서 순서를 정한다

public class EmbeddedSpringMain {

    public static void main(String[] args) throws Exception {
        System.out.println("1. 스프링 컨테이너를 만든다");
        AnnotationConfigWebApplicationContext ctx =
                new AnnotationConfigWebApplicationContext();
        ctx.register(SpringConfig.class);

        System.out.println("2. 디스패처를 만든다");
        DispatcherServlet dispatcher = new DispatcherServlet(ctx);

        System.out.println("3. 톰캣을 만든다");
        Tomcat tomcat = new Tomcat();
        tomcat.setPort(8080);
        tomcat.setBaseDir("/tmp/embedded-spring");

        Context context = tomcat.addContext("", "/tmp/embedded-spring");
        tomcat.addServlet("", "dispatcher", dispatcher);
        context.addServletMappingDecoded("/", "dispatcher");

        System.out.println("4. 시작한다");
        tomcat.start();
        tomcat.getServer().await();
    }
}

